<?php

function is_valid_json($json_string) {
  // Check if the input string is empty or not a string
  if (!is_string($json_string) || empty($json_string)) {
    return false;
  }

  // Decode the input string and check for errors
  $data = json_decode($json_string);
  if ($data === null && json_last_error() !== JSON_ERROR_NONE) {
    return false;
  }

  // Check if the decoded data is an array or an object
  if (!is_array($data) && !is_object($data)) {
    return false;
  }

  // If all checks passed, return true
  return true;
}

// Test the function with some examples
$input1 = '{"name": "John", "age": 30, "city": "New York"}';
$input2 = '{"name": "John", "age": 30, "city": "New York"';
$input3 = '{name: "John", age: 30, city: "New York"}';
$input4 = '["apple", "banana", "cherry"]';

echo is_valid_json($input1) ? 'Valid' : 'Invalid'; // Output: Valid
echo is_valid_json($input2) ? 'Valid' : 'Invalid'; // Output: Invalid
echo is_valid_json($input3) ? 'Valid' : 'Invalid'; // Output: Invalid
echo is_valid_json($input4) ? 'Valid' : 'Invalid'; // Output: Valid

?>
```

